import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"2017-DEC-06 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2017-DEC-06 :: Ceph Developer Monthly","date":"2017-12-19T00:00:00.000Z","updated":"2017-12-20T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.md"};function p(s,l,n,_,a,C){return i(),t("div",null,[...l[0]||(l[0]=[o("<p>本次会议主要讨论了 Ceph 项目的进展和未来规划，涵盖了多个关键议题：</p><p><strong>一、Ceph 路线图概述</strong></p><ul><li><strong>存储技术发展趋势</strong>： 硬盘容量增加，NVMe 成为主流，闪存部署增加，未来将全面转向闪存。</li><li><strong>性能重构</strong>： <ul><li>采用 DPDK 和 SPDK 进行网络和存储 IO。</li><li>对 OSD 进行大量重构，使其更加模块化、异步和事件驱动。</li><li>探索使用未来编程框架，以简化代码并提高可维护性。</li></ul></li><li><strong>代码轻量化</strong>： 减少数据结构和数据复制，避免不必要的内存分配，提高 CPU 利用率。</li><li><strong>撕裂 (Tearing)</strong>： 讨论了撕裂技术的改进方案，包括： <ul><li>用更传统的撕裂模型替换现有的缓存撕裂模型。</li><li>使用完整的索引和基础层，简化代码并提高灵活性。</li></ul></li><li><strong>不同类型的存储池</strong>： 探索实现不同类型的存储池，例如： <ul><li>非复制池，直接写入 SBDK。</li><li>并行写入多个副本的池，具有不同的一致性和容错模型。</li><li>适用于 fabrics 的池，直接在 fabrics 上写入所有副本。</li></ul></li></ul><p><strong>二、其他议题</strong></p><ul><li><strong>消息传递协议</strong>： 讨论了改进消息传递协议，以提高效率和性能。</li><li><strong>CephOSD 重构</strong>： 探索使用 C++ 协程或其他异步编程框架重构 CephOSD。</li><li><strong>PT 合并</strong>： 讨论了解决 PT 合并问题的方案，包括： <ul><li>使 PT 在合并前靠近彼此。</li><li>对齐 PT 日志，以便进行合并。</li><li>确保合并过程的可逆性。</li></ul></li></ul><p><strong>三、行动计划</strong></p><ul><li>继续探索 DPDK、SPDK、未来编程框架等技术的应用。</li><li>对 CephOSD 进行重构，以提高性能和可维护性。</li><li>实现不同类型的存储池。</li><li>改进撕裂技术和 PT 合并。</li><li>探索使用 C++ 协程或其他异步编程框架重构 CephOSD。</li><li>定期讨论 CephOSD 重构和 PT 合并问题。</li></ul><p><strong>四、其他</strong></p><ul><li>提到了 Red Hat 正在进行的 Ceph 仪表板开发项目。</li><li>提到了 Ceph 对象存储网关 (RGW) 的云同步功能。</li></ul><p>本次会议讨论了 Ceph 项目的多个重要议题，并明确了后续行动计划，鼓励大家积极参与相关开发工作。</p>",10)])])}const h=e(r,[["render",p]]);export{D as __pageData,h as default};
